import Image from "next/image";
import Link from "next/link";

import { Button } from "@buttons/button";
import { Badge } from "@ui-core/badge";

export function Hero({
	title,
	description,
	buttonText,
	buttonLink,
	backgroundImage,
}: {
	title: string;
	description: string;
	buttonText: string;
	buttonLink: string;
	backgroundImage: string;
}) {
	return (
		<div className="relative h-[600px] w-full bg-foreground/10">
			<div className="relative z-10 flex h-full flex-col items-center justify-center px-4 text-center sm:px-6 lg:px-8">
				<div className="mx-auto max-w-3xl">
					<Badge variant="secondary" className="mb-4">
						Coming soon
					</Badge>
					<h1 className="font-bold text-4xl tracking-tight sm:text-5xl md:text-6xl">
						{title}
					</h1>
					<p className="mt-6 text-xl">{description}</p>
					<div className="mt-10">
						<Button
							asChild
							variant="secondary"
							size="lg"
							className="rounded-md px-8"
						>
							<Link href={buttonLink}>{buttonText}</Link>
						</Button>
					</div>
				</div>
			</div>
		</div>
	);
}

import React, { type ReactNode } from "react";

export default function MinimalLayout({
  children,
}: Readonly<{
  children: ReactNode;
}>) {
  return (
    <main className="mt-16 flex w-full justify-center">
      <div className="container">{children}</div>
    </main>
  );
}

export default function BlankPage() {
  return (
    <div className="flex flex-col items-center justify-center gap-4 rounded-md py-96">
      <div className="text-muted-foreground">
        Start prompting to use your component!
      </div>
    </div>
  );
}
